use std::fs

fn find(keys: Vec<int>, k: int) -> int {
    let mut i = 0
    while i < keys.len() {
        if keys[i] == k {
            return i as int
        }
        i = i + 1
    }
    -1
}

fn main() {
    let text = fs.read_to_string("/dev/stdin") ?? ""
    let mut keys: Vec<int> = Vec::new()
    let mut vals: Vec<int> = Vec::new()
    let mut cap = 1
    let mut first = true
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() == 0 {
            continue
        }
        if first {
            cap = parts[0].parse::<int>() ?? 1
            first = false
            continue
        }
        let cmd = parts[0]
        if cmd == "put" {
            let k = parts[1].parse::<int>() ?? 0
            let v = parts[2].parse::<int>() ?? 0
            let idx = find(keys, k)
            if idx >= 0 {
                keys.remove(idx as usize)
                vals.remove(idx as usize)
            }
            keys.insert(0, k)
            vals.insert(0, v)
            if keys.len() > cap as usize {
                let last = keys.len() - 1
                let ek = keys[last]
                keys.remove(last)
                vals.remove(last)
                println("evict ${ek}")
            }
        } else if cmd == "get" {
            let k = parts[1].parse::<int>() ?? 0
            let idx = find(keys, k)
            if idx < 0 {
                println("-1")
            } else {
                let v = vals[idx as usize]
                keys.remove(idx as usize)
                vals.remove(idx as usize)
                keys.insert(0, k)
                vals.insert(0, v)
                println("${v}")
            }
        } else if cmd == "keys" {
            if keys.len() == 0 {
                println("<empty>")
            } else {
                let mut s = ""
                let mut i = 0
                while i < keys.len() {
                    if i > 0 {
                        s = s + " "
                    }
                    s = s + "${keys[i]}"
                    i = i + 1
                }
                println(s)
            }
        }
    }
}

